import sys

data = sys.stdin.read().split()
r, c = int(data[0]), int(data[1])
g = [list(data[2 + i]) for i in range(r)]
steps = 0
while True:
    if all(ch == '1' for row in g for ch in row):
        print(steps)
        break
    new = [row[:] for row in g]
    changed = False
    for i in range(r):
        for j in range(c):
            if g[i][j] == '0':
                for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = i + di, j + dj
                    if 0 <= a < r and 0 <= b < c and g[a][b] == '1':
                        new[i][j] = '1'
                        changed = True
                        break
    if not changed:
        print(-1)
        break
    g = new
    steps += 1

